def esc(x):return str(x).replace('\\','\\textbackslash{}').replace('{','\\{').replace('}','\\}').replace('%','\\%').replace('&','\\&').replace('#','\\#').replace('_','\\_')
out=[]
for r in refs:
 year=(re.search(r'(19|20)\d\d',r['date']) or re.search(r'(19|20)\d\d',r['publication'])).group()
 fields={'title':r['title'],'author':r['authors'],'year':year,'howpublished':r['publication'],'url':r['url'],'note':('verified' if r['verified'] else 'unverified')+'; '+r['locator']+'; First circulation: '+r['first_circulation']+'; Scope: '+r['result_used']}
 out.append('@misc{'+r['key']+',\n'+',\n'.join('  '+k+' = {'+(v if k=='url' else esc(v))+'}' for k,v in fields.items())+'\n}')
(P/'references.bib').write_text('\n\n'.join(out)+'\n')
print('Saved',len(refs),'references; metadata-only limits explicitly stated for Imai76, BourbakiAC65, BourbakiCatalog.')
